    catch (e) { error = e.message; }
  }
  if (!recs || !recs.length) return {ok: false, error: error || "la consulta no devolvió datos", rows: []};
  recs = unaCategoria(recs);
  const rows = recs.map(r =&gt; ({
    indicador: spec.nombre,
    codigo_territorio: r.geo ?? "",
    territorio: r.geo ? (nombresGeo[r.geo] ?? r.geoLabel) : (spec.serie ?? spec.nombre),
    periodo: r.time,
    fecha: fecha(r.time),
    valor: r.value,
    unidad: spec.unidad,
    fuente: `Eurostat (${usado.code})`
  })).filter(r =&gt; r.fecha && Number.isFinite(r.valor));
  return {ok: rows.length &gt; 0, rows, code: usado.code, error: rows.length ? "" : "la consulta no devolvió datos"};
}

function colores(terrs) {
  const fijos = {"España": "#B5175F", "Andalucía": "#F29200", "UE-27": "#3C3C3B", "Zona euro": "#7A7A7A"};
  const paleta = ["#1F77B4", "#2CA02C", "#9467BD", "#8C564B", "#17BECF", "#BCBD22", "#E377C2", "#D62728", "#7F7F7F"];
  let k = 0;
  return terrs.map(t =&gt; fijos[t] ?? paleta[k++ % paleta.length]);
}

function csv(rows) {
  return new Blob(["﻿" + d3.csvFormat(rows.map(({fecha, ...r}) =&gt; r))], {type: "text/csv;charset=utf-8"});
}
indInicial = {
  // Permite enlazar directamente a un indicador: pagina.html?i=identificador
  const p = new URLSearchParams(window.location.search).get("i");
  return indicadores.find(d =&gt; d.id === p) ?? indicadores[0];
}
viewof ind = Inputs.select(indicadores, {label: "Indicador", format: d =&gt; d.nombre, value: indInicial})
html`&lt;p class="ind-desc"&gt;${ind.descripcion}&lt;span class="ind-meta"&gt;Unidad: ${ind.unidad} · Frecuencia: ${ind.frecuencia} · Fuente: &lt;a href="https://ec.europa.eu/eurostat/databrowser/view/${ind.code}/default/table" target="_blank" rel="noopener"&gt;Eurostat, ${ind.code}&lt;/a&gt;${ind.regional ? " · Datos regionales (NUTS 2)" : ""} · &lt;a href="?i=${ind.id}" title="Enlace directo a este indicador para compartirlo o ponerlo en una guía docente"&gt;🔗 Enlace a este indicador&lt;/a&gt;&lt;/span&gt;&lt;/p&gt;`
datos = cargar(ind)
territorios = datos.ok ? [...new Set(datos.rows.map(r =&gt; r.territorio))].sort((a, b) =&gt; a.localeCompare(b, "es")) : []
defecto = {
  const d = (ind.regional ? defRegiones : defPaises).map(g =&gt; nombresGeo[g]);
  const v = territorios.filter(t =&gt; d.includes(t));
  return v.length ? v : territorios.slice(0, 5);
}
viewof terr = Inputs.select(territorios, {label: "Territorios (Ctrl/Cmd para elegir varios)", multiple: true, value: defecto, size: Math.min(8, Math.max(2, territorios.length))})
sel = datos.ok ? datos.rows.filter(r =&gt; terr.includes(r.territorio)) : []
datos.ok ? (terr.length ? Plot.plot({
  height: 430, marginLeft: 60, marginRight: 130,
  x: {label: null, type: "time"},
  y: {label: ind.unidad, grid: true, zero: ind.cero ?? false, tickFormat: v =&gt; fmt(v)},
  color: {domain: terr, range: colores(terr)},
  marks: [
    ind.cero ? Plot.ruleY([0], {stroke: "#999"}) : null,
    Plot.line(sel, {x: "fecha", y: "valor", stroke: "territorio", strokeWidth: 2.2, sort: "fecha"}),
    Plot.text(sel, Plot.selectLast({x: "fecha", y: "valor", z: "territorio", text: "territorio", textAnchor: "start", dx: 6, fill: "territorio"})),
    Plot.tip(sel, Plot.pointer({x: "fecha", y: "valor", title: d =&gt; `${d.territorio} · ${d.periodo}\n${fmt(d.valor)} (${ind.unidad})`}))
  ]
}) : html`&lt;p class="pending"&gt;Elige al menos un territorio.&lt;/p&gt;`)
: html`&lt;div class="callout callout-warning"&gt;&lt;p&gt;&lt;b&gt;No se han podido cargar los datos de Eurostat&lt;/b&gt; (${datos.error}). Inténtalo de nuevo más tarde o consulta la tabla directamente en &lt;a href="https://ec.europa.eu/eurostat/databrowser/view/${ind.code}/default/table" target="_blank"&gt;Eurostat&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;`
ultimos = {
  if (!datos.ok) return [];
  const last = d3.rollup(datos.rows, v =&gt; v.sort((a, b) =&gt; b.fecha - a.fecha)[0], d =&gt; d.territorio);
  return [...last.values()].sort((a, b) =&gt; b.valor - a.valor);
}
datos.ok ? Plot.plot({
  height: Math.max(260, 17 * ultimos.length), marginLeft: 150, marginRight: 60,
  x: {label: `${ind.unidad} (último dato disponible)`, grid: true, tickFormat: v =&gt; fmt(v)},
  y: {label: null},
  marks: [
    Plot.barX(ultimos, {y: "territorio", x: "valor", sort: {y: "-x"}, fill: d =&gt; d.territorio === "España" ? "#B5175F" : (d.territorio === "Andalucía" ? "#F29200" : (d.territorio === "UE-27" ? "#3C3C3B" : "#D9C2CC")), tip: true, title: d =&gt; `${d.territorio} (${d.periodo}): ${fmt(d.valor)}`}),
    Plot.text(ultimos, {y: "territorio", x: "valor", text: d =&gt; fmt(d.valor), dx: 4, textAnchor: "start", fontSize: 10}),
    Plot.ruleX([0])
  ]
}) : html``
datos.ok ? html`&lt;div class="descargas"&gt;
  ${DOM.download(() =&gt; csv(sel), `cceescopio_${ind.code}_seleccion.csv`, "⬇ Descargar selección (CSV)")}
  ${DOM.download(() =&gt; csv(datos.rows), `cceescopio_${ind.code}_completo.csv`, "⬇ Descargar todos los territorios (CSV)")}
&lt;/div&gt;
&lt;p class="source"&gt;Datos descargados en directo de Eurostat al abrir la página (último periodo: ${d3.max(datos.rows, d =&gt; d.periodo)}). Reutilización libre citando la fuente: Eurostat (${ind.code}), a través de CCEEscopio, Facultad de Ciencias Económicas y Empresariales, Universidad de Granada.&lt;/p&gt;` : html``
